  {
    "statement": "IF tool_name == \"verify_loan_purpose\" THEN (due_diligence_identity_complete == True AND due_diligence_income_complete == True AND (skip_verification == False OR skip_verification is not provided)) => ALLOW; OTHERWISE => DENY"
