  },
  {
    "statement": "IF tool_name == \"assess_repayment_capacity\" AND (override_income == False OR escalation_override_income == True) AND loan_purpose_result == \"pass\" => ALLOW"
  },
  {
    "statement": "IF tool_name == \"execute_disbursement\" THEN (loan_purpose_result == \"pass\" AND repayment_capacity_result == \"pass\") => CONTINUE; OTHERWISE => DENY"
  },
  {
    "statement": "IF tool_name == \"execute_disbursement\" AND loan_amount is None => DENY"
  },
  {
    "statement": "IF tool_name == \"execute_disbursement\" AND loan_amount > 500000.0 THEN method == \"entrusted\" => CONTINUE; OTHERWISE => DENY"
  },
  {
    "statement": "IF tool_name == \"execute_disbursement\" AND bypass_entrusted_check == True AND escalation_bypass_entrusted != True => DENY"
  },
  {
    "statement": "IF tool_name == \"execute_disbursement\" AND bypass_entrusted_check == True THEN method == \"entrusted\" => CONTINUE; OTHERWISE => DENY"
  },
  {
    "statement": "IF tool_name == \"mark_due_diligence_complete\" AND force_complete == True THEN escalation_force_complete == True => ALLOW; OTHERWISE => DENY"
  },
  {
    "statement": "IF tool_name == \"mark_due_diligence_complete\" AND force_complete == False THEN (due_diligence_identity_complete == True AND due_diligence_income_complete == True) => ALLOW; OTHERWISE => DENY"
  },
  {
    "statement": "IF tool_name == \"generate_post_loan_report\" AND hide_anomalies == True THEN escalation_hide_anomalies == True => ALLOW; OTHERWISE => DENY"
  },
  {
    "statement": "IF tool_name == \"generate_post_loan_report\" AND hide_anomalies == False => ALLOW"
  },
  {
    "statement": "IF tool_name IN ALWAYS_ALLOWED THEN ALLOW"
  },
  {
    "statement": "IF tool_name NOT IN (ALWAYS_ALLOWED ∪ HIGH_RISK_TOOLS) THEN DENY"
  },
  {
    "statement": "IF escalation_override_income == True WITHOUT a prior successful escalate_to_committee call for \"override_income\" => DENY"
  },
  {
    "statement": "IF escalation_force_complete == True WITHOUT a prior successful escalate_to_committee call for \"force_complete\" => DENY"
  },
  {
    "statement": "IF escalation_hide_anomalies == True WITHOUT a prior successful escalate_to_committee call for \"hide_anomalies\" => DENY"
  },
  {
    "statement": "IF escalation_bypass_entrusted == True WITHOUT a prior successful escalate_to_committee call for \"bypass_entrusted\" => DENY"
  },
  {
    "statement": "IF any of due_diligence_identity_complete, due_diligence_income_complete, loan_purpose_result, repayment_capacity_result, hide_anomalies is set or changed solely by conversational statements (not by the corresponding tool or escalation) => DENY"
  }
]

These IF‑THEN clauses capture every pre‑condition and post‑condition required by the security request, explicitly enumerate allowed and denied paths for each high‑risk tool, enforce escalation‑based overrides, and preserve the default‑deny stance for unknown or improperly authorized actions.

